public void initializeSandiumWallpaperBacking(android.widget.ImageView wallpaper) {
    if (mSandiumWallpaperRoot != null) throw new IllegalStateException("Backing already initialized");
    if (mRootView.getParent() != null) throw new IllegalStateException("Backing must precede attachment");
    mSandiumRootBackground = mRootView.getBackground();
    mSandiumRecyclerBackground = mRecyclerView.getBackground();
    if (mNtpHeader != null) mSandiumHeaderBackground = mNtpHeader.getBackground();
    FrameLayout outer = new FrameLayout(mActivity);
    outer.setBackgroundColor(mDefaultBackgroundColor);
    outer.setClipChildren(true);
    mSandiumWallpaperRoot = outer;
    mSandiumWallpaper = wallpaper;
    org.chromium.ui.UiUtils.removeViewFromParent(wallpaper);
    wallpaper.setClickable(false);
    wallpaper.setFocusable(false);
    outer.addView(wallpaper, new FrameLayout.LayoutParams(-1, -1));
    outer.addView(mRootView, new FrameLayout.LayoutParams(-1, -1));
    outer.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob) -> {
        if (r-l != or-ol || b-t != ob-ot) {
            mSandiumWallpaperDirty = true;
            refreshSandiumWallpaperBacking();
        }
    });
    outer.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
        @Override public void onViewAttachedToWindow(View view) { mSandiumWallpaperAttached = true; refreshSandiumWallpaperBacking(); }
        @Override public void onViewDetachedFromWindow(View view) { mSandiumWallpaperAttached = false; refreshSandiumWallpaperBacking(); }
    });
    refreshSandiumWallpaperBacking();
}

