private void refreshSandiumWallpaperBacking() {
    FrameLayout outer = mSandiumWallpaperRoot;
    android.widget.ImageView wallpaper = mSandiumWallpaper;
    if (outer == null || wallpaper == null) return;
    android.graphics.drawable.Drawable drawable = wallpaper.getDrawable();
    boolean paintReady = mSandiumWallpaperAllowed
            && outer.getWidth() > 0 && outer.getHeight() > 0 && drawable != null
            && drawable.getIntrinsicWidth() == outer.getWidth()
            && drawable.getIntrinsicHeight() == outer.getHeight();
    boolean ready = paintReady && mSandiumWallpaperAttached;
    wallpaper.setVisibility(mSandiumWallpaperAllowed ? View.VISIBLE : View.INVISIBLE);
    if (ready == mSandiumWallpaperReady && paintReady == mSandiumWallpaperPaintReady) return;
    mSandiumWallpaperReady = ready;
    mSandiumWallpaperPaintReady = paintReady;
    mSandiumWallpaperDirty = true;
    mRootView.setBackground(paintReady ? null : mSandiumRootBackground);
    mRecyclerView.setBackground(paintReady ? null : mSandiumRecyclerBackground);
    if (mNtpHeader != null) mNtpHeader.setBackground(paintReady ? null : mSandiumHeaderBackground);
    onSandiumWallpaperReadinessChanged(paintReady);
    outer.invalidate();
    for (Runnable observer : new java.util.ArrayList<>(mSandiumWallpaperObservers)) observer.run();
}

