private org.chromium.chrome.browser.feed.@Nullable FeedSurfaceCoordinator mSandiumWallpaperCoordinator;
private org.chromium.components.prefs.@Nullable PrefChangeRegistrar mSandiumWallpaperPrefObserver;

public void attachSandiumWallpaperBacking(org.chromium.chrome.browser.feed.FeedSurfaceCoordinator coordinator) {
    mBgImageView = findViewById(R.id.bg_image_view);
    if (mBgImageView == null || mProfile == null) return;
    mSandiumWallpaperCoordinator = coordinator;
    coordinator.initializeSandiumWallpaperBacking(mBgImageView);
    mSandiumWallpaperPrefObserver = new org.chromium.components.prefs.PrefChangeRegistrar(
            UserPrefs.get(mProfile));
    mSandiumWallpaperPrefObserver.addObserver(BravePref.NEW_TAB_PAGE_SHOW_BACKGROUND_IMAGE,
            () -> maybeShowNTPImage());
    maybeShowNTPImage();
}

public void releaseSandiumWallpaperBacking() {
    if (mSandiumWallpaperPrefObserver != null) {
        mSandiumWallpaperPrefObserver.destroy();
        mSandiumWallpaperPrefObserver = null;
    }
    if (mSandiumWallpaperCoordinator != null) mSandiumWallpaperCoordinator.setSandiumWallpaperAllowed(false);
    mSandiumWallpaperCoordinator = null;
}

private void maybeShowNTPImage() {
    if (mSandiumWallpaperCoordinator != null) {
        mSandiumWallpaperCoordinator.setSandiumWallpaperAllowed(
                mProfile != null && UserPrefs.get(mProfile)
                        .getBoolean(BravePref.NEW_TAB_PAGE_SHOW_BACKGROUND_IMAGE)
                && mSponsoredTab != null && NTPImageUtil.shouldEnableNTPFeature()
                && mNtpImageGlobal != null
                && !(mNtpImageGlobal instanceof Wallpaper
                        && ((Wallpaper) mNtpImageGlobal).isRichMedia()));
    }

@Override
